// The Codex wire boundary checked against the committed app-server protocol
// types (./protocol, generated by Codex 0.163.0; see ./protocol/VERSION and
// ./protocol/CLOSURE.md). Type-level only: nothing here runs. Each check
// fails typecheck when the pinned protocol and the shapes the session reads or
// writes drift apart, so a protocol bump that changes them is caught at the
// boundary rather than at runtime.
// - Reads: every protocol value the session reads (Turn, the token usage,
//   the dynamic tool call, the rate-limit snapshot) is assignable to the
//   session's narrower view of it.
// - Writes: the session's dynamic tool response is a DynamicToolCallResponse;
//   the thread/start tool entries are DynamicToolSpec values and elicitation
//   replies McpServerElicitationRequestResponse values (typed in tools.ts and
//   requests.ts).
// - Modes: the form modes are exactly the protocol's elicitation modes other
//   than the content-free ones.
import type { CodexTokenBreakdown, CodexTurn } from './events.js'
import type { FormMode } from './elicitationForm.js'
import type { CodexDynamicToolCall, CodexDynamicToolResponse } from './tools.js'
import type { DynamicToolCallParams } from './protocol/v2/DynamicToolCallParams.js'
import type { DynamicToolCallResponse } from './protocol/v2/DynamicToolCallResponse.js'
import type { DynamicToolSpec } from './protocol/v2/DynamicToolSpec.js'
import type { McpServerElicitationRequestParams } from './protocol/v2/McpServerElicitationRequestParams.js'
import type { McpServerElicitationRequestResponse } from './protocol/v2/McpServerElicitationRequestResponse.js'
import type { RateLimitSnapshot } from './protocol/v2/RateLimitSnapshot.js'
import type { ThreadTokenUsage } from './protocol/v2/ThreadTokenUsage.js'
import type { TokenUsageBreakdown } from './protocol/v2/TokenUsageBreakdown.js'
import type { Turn } from './protocol/v2/Turn.js'

export type { DynamicToolSpec, McpServerElicitationRequestResponse }

type Assignable<From extends To, To> = [From, To]
type Equal<A, B> = [A] extends [B] ? ([B] extends [A] ? true : false) : false
type True<T extends true> = T

export type ProtocolBoundaryChecks = [
  Assignable<Turn, CodexTurn>,
  Assignable<TokenUsageBreakdown, CodexTokenBreakdown>,
  Assignable<ThreadTokenUsage, { total: CodexTokenBreakdown; last: CodexTokenBreakdown; modelContextWindow: number | null }>,
  Assignable<DynamicToolCallParams, CodexDynamicToolCall>,
  Assignable<RateLimitSnapshot, Record<string, unknown>>,
  Assignable<CodexDynamicToolResponse, DynamicToolCallResponse>,
  True<Equal<FormMode, Exclude<McpServerElicitationRequestParams['mode'], 'url' | 'openai/userVerification'>>>,
]
